#!/usr/bin/env python3
"""Generate the public AI Tool Fit Interview."""
from __future__ import annotations
import html, json
from datetime import date
from pathlib import Path

DOMAIN='https://aitoolsessentials.com'
def esc(v): return html.escape(str(v or ''), quote=True)

def generate(root: Path, today: str) -> Path:
    tools=json.loads((root/'data/tools.json').read_text())
    payload=[]
    for t in tools:
        payload.append({'slug':t['slug'],'name':t['name'],'category':t.get('category',''),'best_for':t.get('best_for',''),'price':t.get('price',''),'rating':t.get('rating',0),'summary':t.get('summary',''),'use_cases':t.get('use_cases',[])[:4],'pros':t.get('pros',[])[:2],'cons':t.get('cons',[])[:2]})
    data=json.dumps(payload,ensure_ascii=False).replace('</','<\\/')
    schema=json.dumps({'@context':'https://schema.org','@type':'WebApplication','name':'AI Tool Fit Interview','url':f'{DOMAIN}/fit-interview/','applicationCategory':'BusinessApplication','dateModified':today,'description':'An explainable interview that matches AI tools to workflow, budget, priorities, and risk tolerance.'})
    page=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Take the AI Tool Fit Interview. Answer a few questions about your workflow, budget, privacy, portability, and complexity tolerance to get explainable AI tool recommendations."><title>AI Tool Fit Interview — Find the Right AI Tool for Your Workflow</title><link rel="canonical" href="{DOMAIN}/fit-interview/"><meta property="og:title" content="AI Tool Fit Interview"><meta property="og:description" content="Explainable AI tool recommendations based on your workflow, budget, priorities, and risk tolerance."><meta property="og:image" content="{DOMAIN}/assets/og-ai-tools.jpg"><link rel="stylesheet" href="/css/styles.css"><link rel="stylesheet" href="/css/share.css"><script type="application/ld+json">{schema}</script></head><body><header class="global-nav"><a class="brand" href="/index.html"><span class="brand-glyph">✦</span><span>AIToolsEssentials</span></a><nav class="nav-links"><a href="/tools/index.html">Tools</a><a href="/comparisons/best-ai-tools.html">Best AI tools</a><a href="/categories/">Categories</a><a href="/guides/switch-guides/">Switching</a><a href="/evidence/">Evidence</a><a href="/benchmarks/">Benchmarks</a></nav><a class="nav-cta" href="/premium/">Premium</a></header><main><section class="scene scene-dark"><div class="fit-hero"><p class="kicker">Decision infrastructure · explainable matching</p><h1>Find the tool that fits your actual workflow.</h1><p class="subhead">This is an interview, not a popularity quiz. Tell us what you need, what you can spend, and what trade-offs you will not accept.</p><p><a class="button button-blue" href="/newsletter/" style="margin-left:8px">Keep/Cut Weekly</a></p></div></section><section class="scene scene-light content-hub"><div class="article-shell wide"><form class="fit-form" id="fit-form"><div class="fit-progress"><span>5 questions</span><span id="fit-progress-label">Start with your workflow</span></div><fieldset><legend>1. What workflow are you solving?</legend><label><input type="radio" name="category" value="all" checked> I want a general recommendation</label>{''.join(f'<label><input type="radio" name="category" value="{esc(t)}"> {esc(t)}</label>' for t in sorted({t['category'] for t in tools}))}</fieldset><fieldset><legend>2. What matters most?</legend><label><input type="radio" name="priority" value="quality" checked> Highest output quality</label><label><input type="radio" name="priority" value="simplicity"> Fastest path to a useful result</label><label><input type="radio" name="priority" value="control"> Control, customization, or integrations</label><label><input type="radio" name="priority" value="portability"> Keeping my options open and avoiding lock-in</label></fieldset><fieldset><legend>3. What budget should the shortlist respect?</legend><label><input type="radio" name="budget" value="free" checked> Free or free tier first</label><label><input type="radio" name="budget" value="low"> Prefer under roughly $25/month</label><label><input type="radio" name="budget" value="flexible"> Pay for a strong fit</label></fieldset><fieldset><legend>4. How much complexity can you tolerate?</legend><label><input type="radio" name="complexity" value="low" checked> Keep setup and learning light</label><label><input type="radio" name="complexity" value="medium"> Some setup is fine</label><label><input type="radio" name="complexity" value="high"> I want maximum control</label></fieldset><fieldset><legend>5. What should the recommendation emphasize?</legend><label><input type="radio" name="risk" value="evidence" checked> Clear evidence and transparent trade-offs</label><label><input type="radio" name="risk" value="speed"> Speed and convenience</label><label><input type="radio" name="risk" value="value"> Cost discipline</label></fieldset><button class="button button-blue" type="submit">Show my explainable shortlist →</button></form><section id="fit-results" class="fit-results" hidden><div class="fit-results-head"><span class="kicker light">Your explainable shortlist</span><h2>Start with these three, then verify the fit.</h2><p>These are workflow matches—not universal rankings. Each reason comes from the tool's category, stated use cases, price field, and review evidence.</p></div><div id="fit-cards" class="fit-cards"></div><p class="fit-disclaimer"><strong>Important:</strong> This interview does not know your private data, exact usage volume, or team constraints. Read the evidence, run the trial checklist, and compare at least one alternative before paying.</p><p><button class="button button-dark" id="fit-reset" type="button">Retake interview</button><a class="button button-blue" href="/decision-brief.html">Turn this into a decision brief</a></p></section></div></section></main><footer class="footer"><span>© 2026 AIToolsEssentials</span><a href="/evidence/">Evidence ledger</a><a href="/confidence-check/">Confidence check</a><a href="/methodology/">Methodology</a><a href="/legal/corrections.html">Corrections</a><a href="mailto:contact@aitoolsessentials.com">Contact</a></footer><script type="application/json" id="fit-data">{data}</script><script src="/js/fit-interview.js" defer></script><script src="/js/analytics.js" defer></script></body></html>'''
    out=root/'fit-interview'/'index.html'; out.parent.mkdir(exist_ok=True); out.write_text(page); return out

if __name__=='__main__':
    generate(Path(__file__).resolve().parent.parent,date.today().isoformat())
